CREATE TABLE IF NOT EXISTS ward_boundary_artifacts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_id uuid NOT NULL REFERENCES ward_authoritative_sources(id), artifact_url text NOT NULL, content_type text, byte_size bigint, sha256 text, geometry_status text NOT NULL DEFAULT 'UNCHECKED', provenance_status text NOT NULL DEFAULT 'UNVERIFIED', verification_status text NOT NULL DEFAULT 'UNVERIFIED', extracted_feature_count integer, notes text, created_at timestamptz NOT NULL DEFAULT now(), verified_at timestamptz);